PRAGMA foreign_keys=ON;
CREATE TABLE subtitle_file(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,source_path TEXT NOT NULL UNIQUE,source_sha256 TEXT NOT NULL,git_blob TEXT NOT NULL,byte_length INTEGER NOT NULL,encoding TEXT NOT NULL,record_count INTEGER NOT NULL,valid_cue_count INTEGER NOT NULL,malformed_count INTEGER NOT NULL,empty INTEGER NOT NULL CHECK(empty IN(0,1)),body_sha256 TEXT NOT NULL,r0_family TEXT NOT NULL,r0_contract TEXT NOT NULL,r0_run TEXT NOT NULL,r0_occurrence_id TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE subtitle_record(id TEXT PRIMARY KEY,file_id TEXT NOT NULL,ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,record_kind TEXT NOT NULL,raw_index TEXT NOT NULL,raw_timing TEXT,parsed_start_ms INTEGER,parsed_end_ms INTEGER,raw_text TEXT NOT NULL,raw_block_sha256 TEXT NOT NULL,UNIQUE(file_id,ordinal),FOREIGN KEY(file_id) REFERENCES subtitle_file(id)) WITHOUT ROWID;
CREATE TABLE subtitle_relation(id TEXT PRIMARY KEY,origin_source_path TEXT NOT NULL,origin_pointer TEXT NOT NULL,relation_kind TEXT NOT NULL,raw_locator TEXT NOT NULL,candidate_boundary TEXT NOT NULL,status TEXT NOT NULL,search_complete INTEGER NOT NULL CHECK(search_complete IN(0,1)),candidate_count INTEGER NOT NULL,UNIQUE(origin_source_path,origin_pointer,relation_kind,raw_locator)) WITHOUT ROWID;
CREATE TABLE subtitle_candidate(id TEXT PRIMARY KEY,relation_id TEXT NOT NULL,target_file_id TEXT NOT NULL,target_path TEXT NOT NULL,target_r0_occurrence_id TEXT NOT NULL,UNIQUE(relation_id,target_file_id),FOREIGN KEY(relation_id) REFERENCES subtitle_relation(id),FOREIGN KEY(target_file_id) REFERENCES subtitle_file(id)) WITHOUT ROWID;
CREATE TABLE subtitle_release(id INTEGER PRIMARY KEY CHECK(id=1),manifest_json TEXT NOT NULL) WITHOUT ROWID;
CREATE INDEX subtitle_record_text ON subtitle_record(raw_text);
CREATE INDEX subtitle_candidate_target ON subtitle_candidate(target_file_id,relation_id);
